referenceSolutions.javascript:
export function evalRPN(tokens          )         {
  const stack          =[]; for(const token of tokens) { if(['+','-','*','/'].includes(token)) { const right=stack.pop() ,left=stack.pop() ; stack.push(token==='+'?left+right:token==='-'?left-right:token==='*'?left*right:Math.trunc(left/right)); } else stack.push(Number(token)); } return stack[0];
}

referenceSolutions.typescript:
export function evalRPN(tokens: string[]): number {
  const stack: number[]=[]; for(const token of tokens) { if(['+','-','*','/'].includes(token)) { const right=stack.pop()!,left=stack.pop()!; stack.push(token==='+'?left+right:token==='-'?left-right:token==='*'?left*right:Math.trunc(left/right)); } else stack.push(Number(token)); } return stack[0];
}
